import{_ as o,o as t,c as r,ae as c}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"SOTA: Rust CLI Best Practices in 2026","description":"","frontmatter":{},"headers":[],"relativePath":"sota-rust-cli-2026.md","filePath":"sota-rust-cli-2026.md"}'),d={name:"sota-rust-cli-2026.md"};function i(a,e,s,n,l,p){return t(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="sota-rust-cli-best-practices-in-2026" tabindex="-1">SOTA: Rust CLI Best Practices in 2026 <a class="header-anchor" href="#sota-rust-cli-best-practices-in-2026" aria-label="Permalink to &quot;SOTA: Rust CLI Best Practices in 2026&quot;">​</a></h1><blockquote><p><strong>Status</strong>: Living document. Research snapshot: 2026-06-09. <strong>Scope</strong>: Crate selection for the next generation of Phenotype CLI tooling, with direct reference to the in-tree <code>pheno-cli</code> binary (<code>phenoctl</code>).</p></blockquote><hr><h2 id="executive-summary" tabindex="-1">Executive Summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive Summary&quot;">​</a></h2><p>The 2026 Rust CLI ecosystem is mature and largely converged. A small set of well-maintained crates covers ≥90% of user-facing CLI surface area: argument parsing, progress reporting, interactive prompts, and diagnostic error output. The recommended stack for new HeliosLab/Phenotype CLI work is:</p><table tabindex="0"><thead><tr><th>Concern</th><th>Recommended crate</th><th>Version</th><th>Why</th></tr></thead><tbody><tr><td>Arg parsing</td><td><code>clap</code></td><td>4.6.x</td><td>Derive macros, help, completions, rich error formatter.</td></tr><tr><td>Progress UX</td><td><code>indicatif</code></td><td>0.18.x</td><td>Bounded bars, spinners, templates, <code>HumanBytes</code>.</td></tr><tr><td>Interactive IO</td><td><code>dialoguer</code></td><td>0.12.x</td><td>Confirm, password, select, fuzzy-select, multi-select.</td></tr><tr><td>Diagnostics</td><td><code>miette</code></td><td>7.6.x</td><td>Snippets, labels, error codes, links, screen-reader mode.</td></tr><tr><td>Logging</td><td><code>tracing</code> + <code>tracing-subscriber</code></td><td>0.1 / 0.3</td><td>Structured, level-filtered, span-aware logging.</td></tr><tr><td>TUI</td><td><code>ratatui</code> + <code>crossterm</code></td><td>0.29 / 0.28</td><td>Battle-tested terminal UI in <code>pheno-cli/src/tui.rs</code>.</td></tr></tbody></table><hr><h2 id="_1-argument-parsing-clap-vs-argh-vs-lexopt" tabindex="-1">1. Argument parsing: <code>clap</code> vs <code>argh</code> vs <code>lexopt</code> <a class="header-anchor" href="#_1-argument-parsing-clap-vs-argh-vs-lexopt" aria-label="Permalink to &quot;1. Argument parsing: `clap` vs `argh` vs `lexopt`&quot;">​</a></h2><h3 id="clap-4-6-x-recommended-default" tabindex="-1"><code>clap</code> 4.6.x (recommended default) <a class="header-anchor" href="#clap-4-6-x-recommended-default" aria-label="Permalink to &quot;`clap` 4.6.x (recommended default)&quot;">​</a></h3><ul><li><strong>Current version</strong>: 4.6.1 (per docs.rs).</li><li><strong>MSRV</strong>: 1.74, supports the last two minor Rust releases.</li><li><strong>Strengths</strong>: derive macros, builder API, value parsers, <code>--help</code>, shell completions (<code>clap_complete</code>), man-page generation (<code>clap_mangen</code>), i18n (<code>clap-i18n-richformatter</code>), response files (<code>argfile</code>), and the RichFormatter that suggests fixes on parse errors.</li><li><strong>Drawbacks</strong>: heavier binary size and longer compile time than minimalist alternatives; the <code>derive</code> feature pulls in <code>clap_derive</code>.</li><li><strong>When to use</strong>: any non-trivial CLI with subcommands, validation, or auto-generated help. The de-facto standard in the Rust ecosystem.</li></ul><h3 id="argh-0-1-19" tabindex="-1"><code>argh</code> 0.1.19 <a class="header-anchor" href="#argh-0-1-19" aria-label="Permalink to &quot;`argh` 0.1.19&quot;">​</a></h3><ul><li><strong>Current version</strong>: 0.1.19 (per docs.rs).</li><li><strong>Origin</strong>: Google Fuchsia. Conforms to the Fuchsia commandline tools spec.</li><li><strong>Strengths</strong>: derive-based, optimized for <strong>code size</strong>, fast compile times, predictable help format, dynamic subcommand support.</li><li><strong>Drawbacks</strong>: smaller feature surface (no <code>clap_complete</code> equivalent, no built-in shell completions, less flexible value parsing).</li><li><strong>When to use</strong>: small, embedded, or <code>no_std</code>-adjacent CLIs where every kilobyte of binary size matters.</li></ul><h3 id="lexopt-0-3-2" tabindex="-1"><code>lexopt</code> 0.3.2 <a class="header-anchor" href="#lexopt-0-3-2" aria-label="Permalink to &quot;`lexopt` 0.3.2&quot;">​</a></h3><ul><li><strong>Current version</strong>: 0.3.2 (per docs.rs).</li><li><strong>Strengths</strong>: deliberately minimal, single-file, iterator-style parser. Zero derive macros, zero codegen, minimal dependencies.</li><li><strong>Drawbacks</strong>: you write the parsing loop yourself. No help generation, no validation beyond your own <code>match</code> arms.</li><li><strong>When to use</strong>: tiny utilities (1–3 flags), or when you want full control over the parsing semantics.</li></ul><h3 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to &quot;Verdict&quot;">​</a></h3><p>For <code>phenoctl</code> and similar Phenotype CLIs, <strong>clap with <code>derive</code> is the right choice</strong>. <code>pheno-cli/Cargo.toml:15</code> already declares <code>clap = { version = &quot;4&quot;, features = [&quot;derive&quot;] }</code> and <code>pheno-cli/src/main.rs:9</code> uses <code>#[derive(Parser)]</code> and <code>#[derive(Subcommand)]</code> (lines 9–58). Switching to <code>argh</code> or <code>lexopt</code> would cost us auto-generated <code>--help</code>, subcommand discovery, value parsers, and shell completions for negligible compile-time savings. Reach for <code>argh</code> only if binary size becomes a hard constraint; reach for <code>lexopt</code> only for ≤2-flag utilities.</p><hr><h2 id="_2-progress-reporting-indicatif-0-18-x" tabindex="-1">2. Progress reporting: <code>indicatif</code> 0.18.x <a class="header-anchor" href="#_2-progress-reporting-indicatif-0-18-x" aria-label="Permalink to &quot;2. Progress reporting: `indicatif` 0.18.x&quot;">​</a></h2><ul><li><strong>Current version</strong>: 0.18.4 (per docs.rs).</li><li><strong>Capabilities</strong>: <code>ProgressBar</code> (bounded bars), unbounded spinners (<code>new_spinner</code> + <code>enable_steady_tick</code>), <code>MultiProgress</code> for parallel workers, <code>ProgressIterator</code> for one-liner integration, optional Rayon support (<code>features = [&quot;rayon&quot;]</code>).</li><li><strong>Template system</strong>: <code>{elapsed_precise} {bar:40.cyan/blue} {pos:&gt;7}/{len:7} {msg}</code>-style placeholders; color via <code>console</code>.</li><li><strong>Human formatting</strong>: <code>HumanBytes</code>, <code>BinaryBytes</code>, <code>DecimalBytes</code>, <code>HumanDuration</code>, <code>HumanCount</code>, <code>HumanFloatCount</code> — drop-in wrappers for user-facing byte/time/count strings.</li><li><strong>TTY-aware</strong>: bars are silently hidden when stderr is not a terminal, so logs and pipes stay clean.</li><li><strong>Recommendation</strong>: add <code>indicatif</code> to <code>pheno-cli</code> to wrap the secret encryption in <code>pheno-cli/src/main.rs:323-332</code> (where the user is prompted for a password and a key is loaded from the environment) — these are the long-running operations users will want feedback on. Also wrap bulk operations in any future <code>phenoctl flags audit</code> or <code>phenoctl migrate</code> commands.</li></ul><hr><h2 id="_3-interactive-prompts-dialoguer-0-12-x" tabindex="-1">3. Interactive prompts: <code>dialoguer</code> 0.12.x <a class="header-anchor" href="#_3-interactive-prompts-dialoguer-0-12-x" aria-label="Permalink to &quot;3. Interactive prompts: `dialoguer` 0.12.x&quot;">​</a></h2><ul><li><strong>Current version</strong>: 0.12.0 (per docs.rs).</li><li><strong>Capabilities</strong>: <code>Confirm</code>, <code>Input&lt;T&gt;</code>, <code>Password</code>, <code>Select&lt;T&gt;</code>, <code>MultiSelect&lt;T&gt;</code>, <code>FuzzySelect&lt;T&gt;</code>, <code>Sort&lt;T&gt;</code>, <code>Editor</code> (behind features).</li><li><strong>Ecosystem</strong>: from the <code>console-rs</code> org alongside <code>indicatif</code> and <code>console</code>, so the three share styling primitives and TTY detection.</li><li><strong>Recommendation</strong>: replace <code>rpassword</code> (currently the only prompt dependency in <code>pheno-cli/Cargo.toml:20</code>) with <code>dialoguer::Password</code> to consolidate the prompt surface area and gain TTY detection for free. The call site at <code>pheno-cli/src/main.rs:323</code> (<code>rpassword::prompt_password(&quot;Enter secret value: &quot;)</code>) is a one-line swap. When we add interactive flows (e.g. multi-select for which flags to retire, fuzzy-select for which secret to delete), <code>dialoguer</code> is the obvious choice.</li></ul><hr><h2 id="_4-diagnostics-miette-7-6-x" tabindex="-1">4. Diagnostics: <code>miette</code> 7.6.x <a class="header-anchor" href="#_4-diagnostics-miette-7-6-x" aria-label="Permalink to &quot;4. Diagnostics: `miette` 7.6.x&quot;">​</a></h2><ul><li><strong>Current version</strong>: 7.6.0 (per docs.rs).</li><li><strong>MSRV</strong>: 1.70.</li><li><strong>Capabilities</strong>: a generic <code>Diagnostic</code> protocol with <ul><li>error codes (<code>code(my_app::my_error)</code>) rendered as clickable links in supporting terminals,</li><li><code>url(docsrs)</code> shorthand that auto-links to docs.rs,</li><li>source-code snippets with <code>#[label(...)]</code> and <code>#[label(primary, ...)]</code> annotations,</li><li><code>help</code> text (attribute or field),</li><li><code>severity</code> (<code>Error</code> / <code>Warning</code>),</li><li><code>#[related]</code> aggregation of multiple errors into one report,</li><li><code>fancy</code> feature flag for ANSI-colored graphical output, with a narratable (screen-reader) handler that activates automatically under <code>NO_COLOR=1</code> and on CI,</li><li><code>IntoDiagnostic</code> + <code>Report</code> + <code>miette!</code>/<code>bail!</code>/<code>ensure!</code> macros that match the <code>anyhow</code>/<code>eyre</code> ergonomics.</li></ul></li><li><strong>Recommendation</strong>: introduce <code>miette</code> as the error type for the <code>phenoctl</code> binary, not for the library crates. Per the <code>miette</code> docs: <em>&quot;Use this <code>Result</code> type (or its expanded version) as the return type throughout your app (but NOT your libraries! Those should always return concrete types!).&quot;</em> Library crates (<code>pheno-core</code>, <code>pheno-db</code>, <code>pheno-crypto</code>) should keep returning concrete <code>thiserror</code>-derived types; <code>pheno-cli</code> is the right layer to wrap them in <code>miette::Report</code> for pretty printing. The current <code>pheno-cli/src/main.rs:130-136, 152-155, 211-217, 256-260, 263-266, 313-320, 421-426</code> all use <code>eprintln!</code> + <code>std::process::exit(1)</code>. A <code>miette</code>-based refactor would (a) produce one-line <code>Result&lt;()&gt;</code> returns, (b) include error codes that link to docs, and (c) integrate with <code>tracing</code> so the same error renders in logs and on stderr.</li></ul><hr><h2 id="_5-cross-cutting-concerns" tabindex="-1">5. Cross-cutting concerns <a class="header-anchor" href="#_5-cross-cutting-concerns" aria-label="Permalink to &quot;5. Cross-cutting concerns&quot;">​</a></h2><ul><li><strong>Logging</strong>: keep <code>tracing</code> + <code>tracing-subscriber</code> (already in <code>pheno-cli/Cargo.toml:21</code>). Add <code>tracing-miette</code> to layer miette&#39;s graphical output over <code>tracing_error::SpanTrace</code>. Add <code>clap-verbosity-flag</code> to wire up <code>-v</code>/<code>-vv</code>/<code>-vvv</code> to the subscriber&#39;s <code>EnvFilter</code>.</li><li><strong>Config</strong>: <code>figment</code> or <code>config</code> for layered config (file + env + flags); <code>directories</code> to discover XDG paths.</li><li><strong>Shell completions</strong>: <code>clap_complete</code> is a one-line addition that gives us bash/zsh/fish/PowerShell completions for free.</li><li><strong>Man pages</strong>: <code>clap_mangen</code> for roff source → system man pages.</li><li><strong>Distribution</strong>: <code>cargo dist</code> (built on <code>cargo-build</code> + <code>cargo-packager</code>) is the 2026 default for cross-platform binaries; ditto for Homebrew taps and <code>cargo binstall</code> support.</li><li><strong>Testing</strong>: <code>assert_cmd</code> + <code>assert_fs</code> + <code>predicates</code> for CLI integration tests; <code>trycmd</code> / <code>snapbox</code> for snapshot tests of <code>--help</code> and command output.</li></ul><hr><h2 id="_6-action-items-for-pheno-cli" tabindex="-1">6. Action items for <code>pheno-cli</code> <a class="header-anchor" href="#_6-action-items-for-pheno-cli" aria-label="Permalink to &quot;6. Action items for `pheno-cli`&quot;">​</a></h2><ol><li><strong>Keep</strong> <code>clap = { version = &quot;4&quot;, features = [&quot;derive&quot;] }</code> — the right choice for a multi-subcommand, multi-flag binary.</li><li><strong>Add</strong> <code>indicatif = &quot;0.18&quot;</code> and wrap any future bulk operations in a <code>ProgressBar</code> (e.g. mass <code>flags audit</code>).</li><li><strong>Swap</strong> <code>rpassword</code> for <code>dialoguer = { version = &quot;0.12&quot;, features = [&quot;password&quot;] }</code> to consolidate prompt UX.</li><li><strong>Add</strong> <code>miette = { version = &quot;7&quot;, features = [&quot;fancy&quot;] }</code> and refactor the 8+ <code>eprintln!</code> / <code>process::exit(1)</code> call sites in <code>pheno-cli/src/main.rs</code> to return <code>miette::Result&lt;()&gt;</code> from <code>main</code>.</li><li><strong>Add</strong> <code>clap_complete</code> and <code>clap-verbosity-flag</code> for completions and standard <code>-v</code> handling.</li><li><strong>Add</strong> <code>assert_cmd</code> dev-dependency for end-to-end CLI testing of the subcommand surface.</li></ol><p>The existing <code>pheno-cli</code> already uses the canonical TUI pair (<code>ratatui</code> + <code>crossterm</code>) and the canonical logger (<code>tracing-subscriber</code>), so the rest of the stack is in good shape — the gaps are <code>indicatif</code>, <code>dialoguer</code>, <code>miette</code>, and shell-completion support.</p><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>clap 4.6.1 docs — <a href="https://docs.rs/clap/4.6.1/clap/" target="_blank" rel="noreferrer">https://docs.rs/clap/4.6.1/clap/</a></li><li>argh 0.1.19 docs — <a href="https://docs.rs/argh/0.1.19/argh/" target="_blank" rel="noreferrer">https://docs.rs/argh/0.1.19/argh/</a></li><li>lexopt 0.3.2 docs — <a href="https://docs.rs/lexopt/0.3.2/lexopt/" target="_blank" rel="noreferrer">https://docs.rs/lexopt/0.3.2/lexopt/</a></li><li>indicatif 0.18.4 docs — <a href="https://docs.rs/indicatif/0.18.4/indicatif/" target="_blank" rel="noreferrer">https://docs.rs/indicatif/0.18.4/indicatif/</a></li><li>dialoguer 0.12.0 docs — <a href="https://docs.rs/dialoguer/0.12.0/dialoguer/" target="_blank" rel="noreferrer">https://docs.rs/dialoguer/0.12.0/dialoguer/</a></li><li>miette 7.6.0 docs — <a href="https://docs.rs/miette/7.6.0/miette/" target="_blank" rel="noreferrer">https://docs.rs/miette/7.6.0/miette/</a></li><li><em>Command Line Applications in Rust</em> — <a href="https://rust-cli.github.io/book/" target="_blank" rel="noreferrer">https://rust-cli.github.io/book/</a></li><li><em>pheno-cli source</em> — <code>pheno-cli/src/main.rs</code>, <code>pheno-cli/src/tui.rs</code>, <code>pheno-cli/Cargo.toml</code></li></ul>',35)])])}const u=o(d,[["render",i]]);export{g as __pageData,u as default};
